mapper.select:
SELECT r.*, school.title AS school_name, instance.title AS instance_name, game.title AS game_name, student.student_id AS effective_student_id, student.student_name, student.student_no, student.gender AS student_gender, COALESCE(r.department_id, student.department_id) AS effective_department_id, department.title AS department_name, CASE WHEN COALESCE(department.parent_id, 0) = 0 THEN department.title ELSE faculty.title END AS faculty_name, feedback.record_id AS feedback_record_id, feedback.questionnaire_version AS feedback_version, feedback.question1_answers AS feedback_question1_answers, feedback.question1_other AS feedback_question1_other, feedback.show_question2 AS feedback_show_question2, feedback.question2_answer AS feedback_question2_answer, feedback.question2_other AS feedback_question2_other, feedback.question3_answers AS feedback_question3_answers, feedback.question3_other AS feedback_question3_other, feedback.submitted_time AS feedback_submitted_time FROM gkzh_zycck_record r LEFT JOIN gkzh_school school ON school.school_id = r.school_id LEFT JOIN gkzh_activity_week_instance instance ON instance.instance_id = r.instance_id LEFT JOIN gkzh_activity_game game ON game.game_id = r.game_id AND game.instance_id = r.instance_id
LEFT JOIN gkzh_student student ON student.student_id = COALESCE( (SELECT s.student_id FROM gkzh_student s WHERE s.student_id = r.student_id AND s.user_id = r.user_id AND s.school_id = r.school_id AND s.del_flag = '0'), (SELECT s.student_id FROM gkzh_student s WHERE s.user_id = r.user_id AND s.school_id = r.school_id AND s.del_flag = '0' ORDER BY s.student_id LIMIT 1)) LEFT JOIN gkzh_school_department department ON department.department_id = COALESCE(r.department_id, student.department_id) AND department.school_id = r.school_id
LEFT JOIN gkzh_school_department faculty ON faculty.department_id = department.parent_id AND faculty.school_id = r.school_id LEFT JOIN gkzh_zycck_activity_feedback feedback ON feedback.record_id = r.record_id WHERE r.game_type = 'zycck' AND r.school_id = #{schoolId} AND r.instance_id = #{instanceId}
AND r.status = 'finished' AND (r.status IS NULL OR r.status <> 'finished') AND r.stage = 'activity_feedback' AND (r.status IS NULL OR r.status <> 'finished') AND (r.stage IS NULL OR r.stage <> 'activity_feedback')
AND r.scan_time >= #{startTime} AND r.scan_time < #{endExclusive}
AND (department.department_id = #{departmentId} OR faculty.department_id = #{departmentId})
AND COALESCE(NULLIF(TRIM(r.major), ''), department.title) LIKE CONCAT('%', #{major}, '%')
AND (CASE WHEN COALESCE(NULLIF(TRIM(r.gender), ''), NULLIF(TRIM(student.gender), ''), '其他') IN ('0', '男') THEN '男' WHEN COALESCE(NULLIF(TRIM(r.gender), ''), NULLIF(TRIM(student.gender), ''), '其他') IN ('1', '女') THEN '女' ELSE '其他' END) = #{gender}
AND student.student_no LIKE CONCAT('%', #{studentNo}, '%')
AND r.record_id > #{afterId} ORDER BY r.record_id LIMIT #{limit}
